using System;using System.Collections.Generic;using System.Numerics;using System.Text.Json;using EDJP.Observatory.Solver;
class Program{static void Main(){var cases=new List<object>();for(int seed=0;seed<12;seed++){var random=new Random(seed);int count=seed+2;var points=new List<Vector3>();for(int i=0;i<count;i++)points.Add(new Vector3(random.Next(-10000,10000)/3f,random.Next(-10000,10000)/7f,random.Next(-10000,10000)/11f));var result=Tsp3DSolver.SolveExact(points,0,null,true);cases.Add(new{points=points.ConvertAll(p=>new[]{p.X,p.Y,p.Z}),order=result.Order,length=result.Length});}Console.Write(JsonSerializer.Serialize(cases));}}
